      ui: { todayReady: "Le défi du jour est prêt. Lancez-vous quand vous voulez.", practiceReady: "La grille d’entraînement est prête. Lancez-vous quand vous voulez.", timerStarted: "Le chrono est lancé. À vous de jouer !", puzzleReset: "Grille réinitialisée. Lancez-vous quand vous êtes prêt.", pressStartMove: "Lancez la partie avant de jouer.", selectVisibleIsland: "Sélectionnez une île visible pour modifier le nombre de ponts.", islandsNotVisible: "Ces îles ne sont pas directement visibles l’une de l’autre.", hashiConflict: "Un pont, une île ou un croisement ne respecte pas les règles.", markConflict: "Certaines marques ne respectent pas les règles.", pressStartCheck: "Lancez la partie avant de la vérifier.", checkConflicts: "Des erreurs ont été trouvées. Les marques rouges indiquent où regarder.", noConflicts: "Aucune erreur directe pour l’instant. Continuez.", complete: "Grille terminée. Bien joué !", modeDaily: "Défi du jour", modePractice: "Entraînement illimité", timerNote: "Le chrono ne démarre qu’après avoir appuyé sur Lancer.", unique: "Solution unique", valid: "Valide", inProgress: "Partie en cours", startDaily: "Lancer le défi du jour", startPractice: "Lancer l’entraînement", treeCell: "Arbre, ligne {row}, colonne {col}", boardCell: "Ligne {row}, colonne {col}", island: "Île {index}, nécessite {count} ponts", horizontalEdge: "Bord horizontal, ligne {row}, colonne {col}", verticalEdge: "Bord vertical, ligne {row}, colonne {col}", shareComplete: "Grille terminée en {time}.", shareReady: "Le résultat est prêt à être partagé.", shareFallback: "Vous pouvez partager votre résultat avec l’adresse de cette page.", difficulties: { easy: "Facile", medium: "Moyen", hard: "Difficile" } }
