    g: {
      "tents-and-trees": { name: "テント・アンド・ツリー", title: "テント・アンド・ツリー オンライン", seo: "テント・アンド・ツリーを無料で遊ぶ", desc: "テント・アンド・ツリーを無料でプレイ。今日の問題と回数無制限の練習問題を登録なしで楽しめます。", intro: "すべての木の隣にテントを1つ置きます。テント同士は斜め方向も接してはいけません。", prompt: "行と列の数字を手がかりに、すべてのテントを置きましょう。", goal: ["すべての木の隣にテントを1つ置く", "テント同士を接触させない", "各行・各列の数字を満たす"], rules: "各テントは木の上下左右いずれかに置きます。テント同士は上下左右でも斜めでも接してはいけません。", how: "マスをタップすると、空白 → テント → 草の順に切り替わります。置けないマスには草を付けましょう。", tips: "候補が1マスしかない木から始め、必要数を満たした行や列を消去法に使うのがコツです。", faqTitle: "テント・アンド・ツリーのよくある質問", faq: [["テントは斜めに接してもいいですか？", "いいえ。テントの周囲8マスに別のテントを置くことはできません。"], ["練習問題は何度でも遊べますか？", "はい。登録なしで好きなだけ新しい練習問題を作れます。"]], side: "練習問題は無料で回数無制限です。進み具合はこのブラウザに保存されます。" },
      hashi: { name: "橋をかけろ（Hashi）", title: "橋をかけろ オンライン", seo: "橋をかけろ（Hashi）を無料で遊ぶ", desc: "橋をかけろを無料でプレイ。数字の島を橋で結ぶ今日の問題と練習問題を楽しめます。", intro: "すべての島を橋でつなぎ、島に書かれた数字と橋の本数を合わせます。", prompt: "見通せる2つの島を選ぶと、橋が0 → 1 → 2 → 0本の順に変わります。", goal: ["各島の数字と橋の本数を合わせる", "橋を交差させない", "すべての島を1つにつなぐ"], rules: "橋は縦か横に架け、2つの島の間は2本までです。橋同士は交差できず、最後はすべての島がつながります。", how: "島を1つ選び、同じ行か列にある見通せる島を選びます。繰り返すと橋の本数が変わります。", tips: "数字が1や2の島から考えましょう。数字を満たした島には、それ以上橋を足せません。", faqTitle: "橋をかけろのよくある質問", faq: [["2つの島の間に橋は何本まで架けられますか？", "0本、1本、または2本です。"], ["橋は島を通り抜けられますか？", "いいえ。手前にある島で橋は止まります。"]], side: "島を選んでから、見通せる島を選びます。橋は0本、1本、2本の順に切り替わります。" },
      slitherlink: { name: "スリザーリンク", title: "スリザーリンク オンライン", seo: "スリザーリンクを無料で遊ぶ", desc: "スリザーリンクを無料でプレイ。数字を手がかりに、分岐のない1本の輪を完成させましょう。", intro: "数字のマスを囲むように、交差も分岐もしない1本の輪を描きます。", prompt: "辺をタップすると、未確定 → 線 → × → 未確定の順に変わります。", goal: ["すべての数字を満たす", "閉じた輪を1つ作る", "交差や分岐を作らない"], rules: "数字は、そのマスの4辺のうち線になる本数を表します。完成する線は途切れず、閉じた1本の輪になります。", how: "1回タップすると線、2回目で×、3回目で消去です。線を引かない辺には×を付けましょう。", tips: "0の周囲はすべて×、3の周囲は3本が線です。線が通る交点では、最終的に2本の線がつながります。", faqTitle: "スリザーリンクのよくある質問", faq: [["数字は何を表していますか？", "そのマスの4辺のうち、輪に使う辺の正確な本数です。"], ["線を分岐させてもいいですか？", "いいえ。線を使う交点には必ず2本だけがつながります。"]], side: "辺をタップして、未確定・線・×を切り替えます。数字の本数は必ず一致します。" },
      nonogram: { name: "ノノグラム", title: "ノノグラム オンライン", seo: "ノノグラム・お絵かきロジックを無料で遊ぶ", desc: "ノノグラム（お絵かきロジック）を無料でプレイ。行と列の数字から絵を完成させましょう。", intro: "行と列の数字を手がかりにマスを塗り、隠れた白黒の絵を完成させます。", prompt: "マスをタップすると、未確定 → 塗る → × → 未確定の順に変わります。", goal: ["各行の数字を満たす", "各列の数字を満たす", "隠れた絵を完成させる"], rules: "数字は連続して塗るマスのまとまりを表します。複数のまとまりの間には、空きマスが1つ以上入ります。", how: "1回タップで塗り、2回目で×、3回目で消去します。スマートフォンでも同じ操作です。", tips: "長い数字から置ける範囲を重ねて考えましょう。すでに付けた×も候補を絞る手がかりになります。", faqTitle: "ノノグラムのよくある質問", faq: [["ノノグラムとは何ですか？", "数字を手がかりに絵を完成させるパズルで、お絵かきロジックやPicrossとも呼ばれます。"], ["スマートフォンでも遊べますか？", "はい。タップだけで3つの状態を切り替えられます。"]], side: "タップで未確定 → 塗る → ×を切り替えます。パソコンでは右クリックでも×を付けられます。" }
    }
